import type { TraceNode } from "../types";
import { esc } from "./format";

function words(text: string) {
  return [...text.matchAll(/[\p{L}\p{N}]+(?:['’][\p{L}\p{N}]+)*/gu)].map((m) => ({
    value: m[0].toLowerCase().replace(/’/g, "'"),
    start: m.index!,
    end: m.index! + m[0].length,
  }));
}
type Word = ReturnType<typeof words>[number];
const key = (tokens: Word[], i: number) => tokens.slice(i, i + 3).map((w) => w.value).join(" ");

/** Link repeated phrases to another post in this trace, preserving the displayed text.
 * Three words and twelve characters avoid turning isolated common words into links.
 * These are navigation aids, not additional copy/coordination evidence. */
export function sharedTextHtml(node: TraceNode, nodes: TraceNode[]): string {
  const tokens = words(node.text);
  const peers = new Map<string, { node: TraceNode; tokens: Word[]; at: number }[]>();
  for (const peer of nodes) {
    if (peer.id === node.id) continue;
    const other = words(peer.text);
    for (let at = 0; at + 2 < other.length; at++) {
      const phrase = key(other, at);
      const entry = { node: peer, tokens: other, at };
      const entries = peers.get(phrase);
      if (entries) entries.push(entry);
      else peers.set(phrase, [entry]);
    }
  }

  let html = "", end = 0;
  for (let i = 0; i + 2 < tokens.length; i++) {
    let best: TraceNode | undefined, length = 0;
    for (const peer of peers.get(key(tokens, i)) ?? []) {
      let count = 3;
      while (i + count < tokens.length && peer.at + count < peer.tokens.length &&
        tokens[i + count].value === peer.tokens[peer.at + count].value) count++;
      if (count > length) { best = peer.node; length = count; }
    }
    if (!best) continue;
    const start = tokens[i].start, stop = tokens[i + length - 1].end;
    if (stop - start < 12) continue;
    html += esc(node.text.slice(end, start));
    html += `<a class="text-match" href="#" data-go="${esc(best.id)}" title="${esc(`View matching text in post by ${best.author.name}`)}">${esc(node.text.slice(start, stop))}</a>`;
    end = stop;
    i += length - 1;
  }
  return html + esc(node.text.slice(end));
}

