        tokens[i + count].value === peer.tokens[peer.at + count].value) count++;
      if (count > length) { best = peer.node; length = count; }
    }
    if (!best) continue;
    const start = tokens[i].start, stop = tokens[i + length - 1].end;
    if (stop - start < 12) continue;
    html += esc(node.text.slice(end, start));
    html += `<a class="text-match" href="#" data-go="${esc(best.id)}" title="${esc(`View matching text in post by ${best.author.name}`)}">${esc(node.text.slice(start, stop))}</a>`;
    end = stop;
    i += length - 1;
  }
